namespace tr=lcbinint::algebraic_boundary::triple;
// Independent scalar five-point differences at rtol=1e-10, with three step
// sizes (1e-3, 5e-4, 2.5e-4). The reference uncertainty includes propagated
// scalar integration errors and step convergence. No derivative controls the
// requested mesh: the fixed offline contract is 1e-4 + 2e-4*abs(reference).
// Pure linear LD additionally uses the exact identity g(1)=2.5*g(.5)-1.5*g(0),
// with the propagated reference uncertainty.
struct Fixture {tr::Geometry geometry;std::array<std::array<double,8>,2> reference,uncertainty;};
